//#region src/r2-concurrency.ts
const MAX_R2_CONCURRENCY = 6;
async function mapSettledWithR2Concurrency(values, callback) {
	const results = [];
	let nextIndex = 0;
	await Promise.all(Array.from({ length: Math.min(MAX_R2_CONCURRENCY, values.length) }, async () => {
		while (nextIndex < values.length) {
			const index = nextIndex++;
			try {
				results[index] = {
					status: "fulfilled",
					value: await callback(values[index])
				};
			} catch (reason) {
				results[index] = {
					status: "rejected",
					reason
				};
			}
		}
	}));
	return results;
}
//#endregion
export { mapSettledWithR2Concurrency };
